def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    candidates = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 7 or seen[r][c]:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)
            height, width = bottom - top + 1, right - left + 1
            if height >= 2 and width >= 2:
                area = height * width
                border = set()
                for x in range(left, right + 1):
                    border.add((top, x))
                    border.add((bottom, x))
                for y in range(top, bottom + 1):
                    border.add((y, left))
                    border.add((y, right))
                if border.issubset(set(cells)):
                    candidates.append((area, top, bottom, left, right))
    if candidates:
        _, top, bottom, left, right = min(candidates)
        for x in range(left + 1, right):
            if top > 0:
                out[top - 1][x] = 2
            if bottom + 1 < h:
                out[bottom + 1][x] = 2
        for y in range(top, bottom + 1):
            if left > 0:
                out[y][left - 1] = 2
            if right + 1 < w:
                out[y][right + 1] = 2
    return out
